// #1d2635 (2056988a22bde8cc1b1d2635) — смена решения о найме с клавиатуры (Space/Enter): после сохранения фокус на
// выбранной кнопке, решение объявляется (role=status «ההחלטה נשמרה: …»). Кейс CAND-011.
// Кандидат с отчётом — QA_KEYBOARD_CANDIDATE (по умолчанию QA-G4b-U-1432, testim). Решение настоящее (PATCH candidates),
// в конце возвращается исходное (последний шаг теста + страховка в finally). Подпись «עודכן על ידי» сменится на
// business — @data.
import * as path from 'path';
import { test, expect, Page } from '@playwright/test';
import { openWithApi } from '../support/api';
import { HIRING, HiringStatus, candidateId, getReport, setDecision } from './hiring-support';

test.use({ storageState: path.resolve(__dirname, '../../../auth/business.json') });

const HASH = '#1d2635 · #2056988a22bde8cc1b1d2635';
const CANDIDATE = process.env.QA_KEYBOARD_CANDIDATE || 'QA-G4b-U-1432';
type Decision = keyof typeof HIRING;
const DECISIONS = Object.keys(HIRING) as Decision[];

const savedResponse = (page: Page) =>
  page.waitForResponse((r) => r.request().method() === 'PATCH' && new URL(r.url()).pathname === '/rest/v1/candidates');

test.describe(`Кандидаты — решение о найме с клавиатуры (${HASH})`, () => {
  test(`Space/Enter: фокус остаётся на выбранной кнопке, role=status «ההחלטה נשמרה: …», Tab не уходит на body; исходное решение возвращено @desktop @data ${HASH}`, async ({ page }) => {
    const api = await openWithApi(page, '/candidates');
    const id = await candidateId(api, CANDIDATE);
    const original = (await getReport(api, id)).hiring?.status as HiringStatus | undefined;
    test.info().annotations.push({ type: 'test-data', description: `решение «${CANDIDATE}» меняется и возвращается к ${original}` });

    try {
      await page.goto(`/candidates/${id}/report`);
      const panel = page.getByTestId('hiring-decision');
      await expect(panel, `у «${CANDIDATE}» нет панели решения (QA_KEYBOARD_CANDIDATE)`).toBeVisible();
      const button = (d: Decision) => panel.locator(`button[data-value="${d}"]`);
      const status = panel.getByRole('status');

      // Порядок: два других решения пробелом, затем исходное — Enter (если исходного нет среди трёх — третье Enter).
      const start = DECISIONS.includes(original as Decision) ? (original as Decision) : null;
      const others = DECISIONS.filter((d) => d !== start);
      const plan: { d: Decision; key: 'Space' | 'Enter' }[] = [
        { d: others[0], key: 'Space' },
        { d: others[1], key: 'Space' },
        { d: start ?? others[0], key: 'Enter' },
      ];

      for (const { d, key } of plan) {
        await button(d).focus();
        await expect(button(d)).toBeFocused();
        const saved = savedResponse(page);
        await page.keyboard.press(key);
        expect((await saved).status(), `PATCH решения «${HIRING[d]}» (${key})`).toBe(200);

        // Источник: AC2 — «הבחירה שנשמרה מוכרזת לקורא מסך».
        await expect(status).toHaveText(`ההחלטה נשמרה: ${HIRING[d]}`);
        await expect(button(d)).toHaveAttribute('aria-pressed', 'true');
        // Источник: AC1 — «המיקוד נשאר על האפשרות שנבחרה או חוזר אליה».
        await expect(button(d), `фокус после ${key} на «${HIRING[d]}»`).toBeFocused();

        // Источник: «מצב קיים» — фокус терялся на body; Tab должен идти дальше от выбранной кнопки.
        await page.keyboard.press('Tab');
        expect(await page.evaluate(() => document.activeElement === document.body || document.activeElement === null), `Tab после «${HIRING[d]}» ушёл на body`).toBe(false);
      }
      if (start) expect((await getReport(api, id)).hiring?.status, 'исходное решение возвращено клавиатурой').toBe(start);
    } finally {
      // Страховка: вернуть исходное решение тем же запросом, что делает UI.
      const now = (await getReport(api, id)).hiring?.status;
      if (original && now !== original) {
        const res = await setDecision(api, id, original);
        expect(res.status(), `возврат исходного решения: ${await res.text()}`).toBe(200);
      }
    }
  });
});
